package communityplus
import("context";"fmt";"os";"os/exec";"path/filepath";"runtime";"strings";"github.com/fleetdm/fleet/v4/server/fleet")
type Client interface{GetCommunityPlusDeployment(string)(*fleet.CommunityPlusWindowsInstallPlan,error);SaveCommunityPlusDeploymentResult(*fleet.CommunityPlusDeploymentResult)error}
type Runner struct{client Client};func NewRunner(client Client)*Runner{return &Runner{client:client}}
func(r *Runner)Run(c *fleet.OrbitConfig)error{if runtime.GOOS!="windows"{return nil};for _,id:=range c.Notifications.PendingCommunityPlusDeploymentIDs{p,e:=r.client.GetCommunityPlusDeployment(id);x:=&fleet.CommunityPlusDeploymentResult{DeploymentID:id,ExitCode:1};if e==nil{x.ExitCode,x.Output,e=execute(context.Background(),p)};if e!=nil&&x.Output==""{x.Output=e.Error()};if e=r.client.SaveCommunityPlusDeploymentResult(x);e!=nil{return fmt.Errorf("save Community+ deployment result: %w",e)}};return nil}
func execute(ctx context.Context,p *fleet.CommunityPlusWindowsInstallPlan)(int,string,error){if p==nil{return 1,"",fmt.Errorf("missing Community+ deployment plan")};if e:=p.Validate();e!=nil{return 1,"",e};s:=fmt.Sprintf("$ErrorActionPreference='Stop'\n$file=Join-Path $env:TEMP ('communityplus-'+ '%s' + '-%s')\nInvoke-WebRequest -Uri '%s' -OutFile $file -UseBasicParsing\nif ((Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash.ToLowerInvariant() -ne '%s') { throw 'Installer SHA-256 mismatch' }\nif ('%s' -eq 'msi') { $existing=Get-ItemProperty HKLM:\\Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\*,HKLM:\\Software\\WOW6432Node\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\* -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -eq '%s' }; if ($existing -and $existing.DisplayVersion -eq '%s') { exit 0 }; $x=Start-Process msiexec.exe -ArgumentList @('/i',$file,'/qn','/norestart') -Wait -PassThru -NoNewWindow; exit $x.ExitCode }; Add-AppxPackage -Path $file -ForceApplicationShutdown",p.DeploymentID,p.InstallerType,p.InstallerURL,strings.ToLower(p.SHA256),p.InstallerType,p.ProductCode,p.Version);d,e:=os.MkdirTemp("","communityplus-");if e!=nil{return 1,"",e};defer os.RemoveAll(d);f:=filepath.Join(d,"install.ps1");if e=os.WriteFile(f,[]byte(s),0600);e!=nil{return 1,"",e};cmd:=exec.CommandContext(ctx,"powershell.exe","-NoProfile","-NonInteractive","-ExecutionPolicy","Bypass","-File",f);o,e:=cmd.CombinedOutput();if e==nil{return 0,string(o),nil};if x,ok:=e.(*exec.ExitError);ok{return x.ExitCode(),string(o),nil};return 1,string(o),e}
